 slider.oninput=()=>{try{const next=model.settings;next.relief.strength=Number(slider.value)/100;previewCandidate=model.candidate(next);clearTimeout(previewTimer);value.textContent=slider.value+'%';previewTimer=setTimeout(()=>{flushPreview();message('Preview updated. Save to keep this finish on this device.')},140)}catch(e){syncStrength();message('Finish unchanged: '+e.message)}};slider.onchange=flushPreview;
 const actions=el('div','lf22-actions');btn(actions,'Save landform finish',()=>{try{flushPreview();localStorage.setItem(STORE,JSON.stringify(model.settings));message('Landform finish saved on this device.')}catch(e){message('Device storage is unavailable. Export the settings to keep this finish.')}});
 btn(actions,'Export landform settings',()=>{flushPreview();const url=URL.createObjectURL(new Blob([JSON.stringify(model.settings,null,2)+'\n'],{type:'application/json'})),a=el('a');a.href=url;a.download='Ancient_Worlds_Landform_Settings.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Exported the applied landform finish.')});
 const file=el('input');file.type='file';file.accept='application/json,.json';file.className='hidden';file.setAttribute('aria-label','Import landform settings');file.onchange=async()=>{const f=file.files?.[0];if(!f)return;try{if(f.size>65536)throw new Error('Settings file exceeds64 KB.');const candidate=JSON.parse(await f.text());apply(candidate);syncStrength();message('Validated finish imported. Save to keep it on this device.')}catch(e){message('Import rejected; finish unchanged: '+e.message)}file.value=''};box.append(file);btn(actions,'Import landform settings',()=>file.click());
 btn(actions,'Reset landform finish',()=>{apply(DEFAULTS);try{localStorage.removeItem(STORE)}catch(e){}syncStrength();message('Default landform finish restored; only this layer’s saved preference was cleared.')});box.append(actions);
 const detail=el('details');detail.append(el('summary','','Resolution and appearance limits'));p(detail,'The two study patches use Copernicus GLO30, a modern30-metre surface model. The inspected older Dead Sea source has90-metre native spacing despite its finer output pixels. Elsewhere, provider detail varies. Output spacing, native source spacing and accuracy are different.');p(detail,'Copernicus heights use EGM2008; the surrounding provider combines other sources and datums. Local source joins can differ, and vegetation or structures can remain in a surface model. Existing water outlines stay independent.');p(detail,'Local-relief contrast changes colour only. It adds no noise, new heights, vegetation measurements, ancient shorelines or historical channels. The existing4% curve and all dated layers retain their registration.');p(detail,'Terrain detail and online terrain must be enabled for new uncached detail. Wider reference imagery remains visible while fine terrain loads or when services are unavailable. Open Detail & sources for terrain controls, tile status and Retry.');detail.append(sourceDetails(DATA.sources.filter(s=>/terrain|elevation|srtm|copernicus|resolution|mapzen|tilezen/i.test(s.title+' '+s.id)).map(s=>s.id)));const rights=el('details');rights.append(el('summary','','Copernicus attribution and licence'));for(const field of ['modifiedAttribution','liabilityNotice','noEndorsement','onwardNotice'])if(LANDFORMS22_TERRAIN.licence[field])p(rights,LANDFORMS22_TERRAIN.licence[field],'lf22-note');const terms=el('details');terms.append(el('summary','','Full source licence'));const text=el('pre','lf22-licence',LANDFORMS22_TERRAIN.licence.text);terms.append(text);rights.append(terms);const link=el('a','','Official source licence');link.href=LANDFORMS22_TERRAIN.licence.url;link.target='_blank';link.rel='noopener noreferrer';rights.append(link);detail.append(rights);box.append(detail);return {box,slider,value};
