function open(){window.worldController?.pauseJourney?.();const box=modal('Landforms and close detail'),shell=el('section','lf22'),hero=el('section','lf22-hero');hero.append(el('div','lf22-kicker','Stone · relief · physical geography'),el('h3','','A closer reading of the landscape'));p(hero,'Two higher-detail pilots use genuine30-metre Copernicus surface data: the western Dead Sea escarpment and a central Zagros study patch. Surrounding terrain retains its established references.');p(hero,'Explore the region’s folded ridges, incised wadis, rift escarpments, river valleys and low alluvial ground. These are modern landform references, kept separate from the changing historical world.');shell.append(hero);const settings=settingsPanel();shell.append(settings.box);const status=el('p','lf22-status');status.setAttribute('role','status');status.textContent=savedNotice;const grid=el('div','lf22-grid');for(const study of DATA.views){const card=el('article','lf22-card');card.dataset.landform=study.id;card.append(el('div','lf22-kicker',study.kind||'Physical landscape'),el('h3','',study.name));p(card,study.summary);if(study.lookFor)p(card,'Look for: '+(Array.isArray(study.lookFor)?study.lookFor.join(' · '):study.lookFor));btn(card,'View '+study.name,()=>locate(study.id));p(card,'Modern relief · viewing position only · atlas date unchanged','lf22-note');if(study.limits)p(card,study.limits,'lf22-note');card.append(sourceDetails(study.sourceIds));grid.append(card)}shell.append(status,grid);box.append(shell);view={shell,status,strength:settings.slider,value:settings.value};return box}
function addTerrainSourceNote(){const box=$('modal');if(box.querySelector('#landforms22-source-note')||box.querySelector('h2')?.textContent!=='Landscape detail')return;const stats=terrain22.stats;if(!stats)return;const note=el('section','lf22-source');note.id='landforms22-source-note';note.append(el('h3','','Packaged study terrain'));p(note,`At panel opening: ${stats.drawableStudyCells} visible cells use Copernicus GLO30 study data; ${stats.drawableBaseCells} use retained broader sources. ${stats.loadedStudyTiles} study tiles are decoded in memory.`,'small muted');p(note,'The source counters above describe the retained provider. These separate study tiles use the same bounded rendering queues and remain outside the Tilezen device cache.','small muted');box.append(note)}
const sourceObserver=typeof MutationObserver==='function'?new MutationObserver(addTerrainSourceNote):null;sourceObserver?.observe($('modal'),{childList:true});
